// Types shared by the whole Hono app: bindings (from wrangler.jsonc + secrets) and per-request variables.
// `Env` itself is generated by `npm run types` into worker-configuration.d.ts.

import type { TokenStore } from "./auth/tokens";
import type { Config } from "./config";
import type { AppSecrets } from "./secrets";
import type { SweatStackClient } from "./sweatstack/client";
import type { Fetch } from "./sweatstack/http";

/** Things the app gets from outside, injectable for tests. */
export type Deps = {
  /** Used for every outbound request (SweatStack, push services). */
  fetch: Fetch;
};

/** The signed-in user, as the session middleware found them. */
export type SessionUser = { id: string; name: string | null; isAdmin: boolean; /** When they first signed in to this app (ms). */ createdAt: number };

export type AppEnv = {
  Bindings: Env;
  Variables: {
    deps: Deps;
    config: Config;
    requestId: string;
    secrets: AppSecrets;
    tokens: TokenStore;
    /** The signed-in user, or null. Use requireUser to make a route sign-in only. */
    user: SessionUser | null;
    /** A SweatStack client for the signed-in user. Only call this behind requireUser. */
    sweatstack: () => SweatStackClient;
  };
};
